//! A fast, deterministic known-answer self-test of the crypto primitives.
//!
//! It serves two purposes. Natively it is an ordinary unit test whose expected values are checked
//! against sodiumoxide, an independent route to the same libsodium C code. On wasm32 it is exported
//! to hosts as `cryptoSelfTest()` (see `wasm_sodium`), so an app can assert at startup that the
//! libsodium.js it injected is the right build and behaves like native, against the very same
//! expected values. None of them was generated by the code under test: they are the FIPS 180 SHA
//! vectors, the RFC 8439 AEAD vector, and values from this project's own pre-existing tests (HMAC,
//! a scrypt key derivation, and a sealed box produced by the original JS client).
//!
//! Takes about a tenth of a second, nearly all of it the scrypt derivation.

// Natively only the tests use this; on wasm32 the exported `cryptoSelfTest()` does.
#![allow(dead_code)]

use ::crypto;
use ::crypto::{CResult, CryptoError, Key};
use ::crypto::low;
use ::crypto::low::chacha20poly1305 as aead;

/// Run every check; the error names the first one that failed.
pub fn run() -> CResult<()> {
    check_hashes()?;
    check_hmac()?;
    check_aead_rfc8439()?;
    check_scrypt()?;
    check_sealed_box()?;
    check_secure_compare()?;
    check_random()?;
    Ok(())
}

fn fail<T>(what: &str) -> CResult<T> {
    Err(CryptoError::OperationFailed(format!("crypto self-test failed: {}", what)))
}

fn check(what: &str, ok: bool) -> CResult<()> {
    if ok { Ok(()) } else { fail(what) }
}

/// Compare `got` with a lowercase hex string.
fn expect_hex(what: &str, got: &Vec<u8>, want_hex: &str) -> CResult<()> {
    if crypto::to_hex(got)? == want_hex { Ok(()) } else { fail(what) }
}

/// FIPS 180 test vectors (SHA-256/512 of "abc") and SHA-256 of the empty input.
fn check_hashes() -> CResult<()> {
    expect_hex("sha256(\"abc\")", &crypto::sha256(b"abc")?,
        "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad")?;
    expect_hex("sha512(\"abc\")", &crypto::sha512(b"abc")?,
        "ddaf35a193617abacc417349ae20413112e6fa4e89a97ea20a9eeee64b55d39a2192992a274fc1a836ba3c23a3feebbd454d4423643ce80e2a9ac94fa54ca49f")?;
    expect_hex("sha256(\"\")", &crypto::sha256(b"")?,
        "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855")
}

/// HMAC-SHA512-256 (libsodium's `crypto_auth`): the expected tag is this project's own
/// (`low.rs`'s `can_hmac_256`).
fn check_hmac() -> CResult<()> {
    let key_source = "Fire them, if they resist, stike or occupy your premises, buy an M134 Minigun to revolve the dispute, then hire new workers";
    let data = "This is a violation of private property rights. They're calling it an issue of zoning. Zoning is communism.";
    let key = crypto::sha512(key_source.as_bytes())?;
    let tag = low::hmac(&key[0..crypto::HMAC_KEYLEN], data.as_bytes())?;
    expect_hex("hmac (HMAC-SHA512-256)", &tag, "9308b40116068920c7cea98aa5bbc340cfabdaa27316413804050cfc6a7b4873")
}

/// RFC 8439 section 2.8.2: the standard ChaCha20-Poly1305 AEAD vector, plus a tamper check.
fn check_aead_rfc8439() -> CResult<()> {
    let key: Vec<u8> = (0x80u8..0xa0u8).collect();
    let nonce = crypto::from_hex(&String::from("070000004041424344454647"))?;
    let aad = crypto::from_hex(&String::from("50515253c0c1c2c3c4c5c6c7"))?;
    let plaintext = b"Ladies and Gentlemen of the class of '99: If I could offer you only one tip for the future, sunscreen would be it.";

    let sealed = aead::encrypt(&key, &nonce, &aad, plaintext)?;
    expect_hex("chacha20poly1305 seal (RFC 8439 2.8.2)", &sealed,
        "d31a8d34648e60db7b86afbc53ef7ec2a4aded51296e08fea9e2b5a736ee62d63dbea45e8ca9671282fafb69da92728b1a71de0a9e060b2905d6a5b67ecd3b3692ddbd7f2d778b8c9803aee328091b58fab324e4fad675945585808b4831d7bc3ff4def08e4b7a9de576d26586cec64b61161ae10b594f09e26a7e902ecbd0600691")?;

    let opened = aead::decrypt(&key, &nonce, &aad, &sealed)?;
    check("chacha20poly1305 open recovers the plaintext", opened.as_slice() == &plaintext[..])?;

    let mut tampered = sealed.clone();
    tampered[0] ^= 1;
    match aead::decrypt(&key, &nonce, &aad, &tampered) {
        Err(CryptoError::Authentication(..)) => Ok(()),
        _ => fail("chacha20poly1305 must reject a tampered ciphertext"),
    }
}

/// scrypt key derivation (`gen_key`): the master-key derivation every login depends on. The
/// expected key is this project's own (`crypto/mod.rs`'s `can_gen_keys`).
fn check_scrypt() -> CResult<()> {
    let username = "andrew@thillygooth.com";
    let password = "this is definitely not the password i use for my bank account. no sir.";
    let salt = crypto::sha512(username.as_bytes())?;
    let key = low::gen_key(
        password.as_bytes(),
        &salt[0..crypto::KEYGEN_SALT_LEN],
        crypto::KEYGEN_OPS_DEFAULT,
        crypto::KEYGEN_MEM_DEFAULT,
    )?;
    expect_hex("scrypt key derivation", &key, "f36850e9bd90afc3413a89693bf71ebdf347f3727bad9b4487e249bb21ca28f1")
}

/// Sealed boxes: open one produced by the original JS client's libsodium.js (this project's own
/// vector, `crypto/mod.rs`'s `asym_crypto`), then a fresh keypair round trip.
fn check_sealed_box() -> CResult<()> {
    let ciphertext = crypto::from_base64(&String::from("A3eNneAydRaXiMB0886wo3sTTAxHcyM7JpaLN4z2rqQRyxUPq/eKrWHyF2/1wC9gfmw5t7lQ6KhT+tSbYTAHQb2EJ3NvwGRyeQ5SXId7RYSAeaoizSyT8JfEI91hyRde3sC5C00xYn60LYjt"))?;
    let pk = Key::new(crypto::from_base64(&String::from("3KhS3n3QlT/w7rE8hwwq/HNnVxlgzkphsqYKRAzbNGg="))?);
    let sk = Key::new(crypto::from_base64(&String::from("ZZN2wHM5T7tUugDGUpMbMB6lI/o5S9AVxjntFjdO+/0="))?);
    let opened = crypto::asym::decrypt(&pk, &sk, ciphertext)?;
    check("sealed box made by the JS client opens",
        opened == b"and if you ever put your god damn hands on my wife again...".to_vec())?;

    let (her_pk, her_sk) = crypto::asym::keygen()?;
    let sealed = crypto::asym::encrypt(&her_pk, b"I'M NOT A PERVERT".to_vec())?;
    let reopened = crypto::asym::decrypt(&her_pk, &her_sk, sealed)?;
    check("sealed box round trip", reopened == b"I'M NOT A PERVERT".to_vec())
}

fn check_secure_compare() -> CResult<()> {
    let a = crypto::sha256(b"harrr")?;
    let b = crypto::sha256(b"harrr")?;
    let c = crypto::sha256(b"child labor")?;
    check("secure_compare accepts equal inputs", low::secure_compare(&a, &b)?)?;
    check("secure_compare rejects different inputs", !low::secure_compare(&a, &c)?)
}

fn check_random() -> CResult<()> {
    let first = low::rand_bytes(32)?;
    let second = low::rand_bytes(32)?;
    check("rand_bytes returns the requested length", first.len() == 32 && second.len() == 32)?;
    check("rand_bytes draws differ", first != second)?;
    check("random_salt has the scrypt salt length", crypto::random_salt()?.len() == crypto::KEYGEN_SALT_LEN)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn self_test_passes_body() {
        run().unwrap();
    }

    fn expect_hex_detects_a_mismatch_body() {
        assert!(expect_hex("same", &vec![1, 2, 3], "010203").is_ok());
        assert!(expect_hex("different", &vec![1, 2, 3], "010204").is_err());
    }

    crypto_test!(self_test_passes, self_test_passes_body);
    crypto_test!(expect_hex_detects_a_mismatch, expect_hex_detects_a_mismatch_body);
}
